quests[93003] = { id = 93003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nArcane power thrums.\nJourney home with a mere step.\nDig beside the roost.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93004] = { id = 93004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nWhere trees have no roots.\nA gate has no door or hinge.\nWill call for treasure.\n\nGood luck!", progress = "You found the treasure!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93005] = { id = 93005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nMushrooms mark the ring.\nDeep within the shadowed wood.\nDig where fireflies swarm.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93006] = { id = 93006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nEarth, fire, smoke, and steam.\nBlade or plow, the shaper's choice.\nLook where metals bend.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93007] = { id = 93007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nAzure and gold sway.\nWhile beneath pretenders play.\nInvestigate stage left.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93008] = { id = 93008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nSix sides, but no walls.\nAfloat above chill waters.\nSecrets wait below.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93009] = { id = 93009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nSeek the smallest house.\nWhere pawsteps mark the sand.\nNow dig where dogs lie.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93043] = { id = 93043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Predator Becomes Prey", progress = "Speak with Astalor Bloodsworn to continue.", completion = "I can assure you that it will seldom be this easy.", objectives = "Survive an ambush by your prey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93047] = { id = 93047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Butchery Basics", description = "We can't keep up with how much these soldiers eat. Lend us just a bit of your time to feed dis army, hm?\n\nWe need boar. Not just a steak or two, we need de entire boar. Nothin' goes to waste, yah?", progress = "De art of Amani huntin' is about discipline. You practice until de skills come as naturally as breathin'.\n\nBut right now, discipline means doin' what I tell you.", completion = "You are an impressive hunter, dat is for sure. Thank you for helpin' us out here.", objectives = "Collect 10 Boar Carcasses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93048] = { id = 93048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Got No Rhythm", description = "Dat boy Kovu stormed out of here without even tryin' a single step. He thinks he's got two left feet, but he isn't even willin' to try.\n\nYou look like an impressive fighter. He'll respect you for dat.\n\nMaybe he just needs de right dance partner to show him de steps. Help him out, hm?", progress = "Makin' progress, yah?", completion = "Dat boy still needs a lot of practice, but you helped him get out of his head and just feel de rhythm.", objectives = "Teach Kovu how to dance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93049] = { id = 93049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Homework Support", description = "<The little girl keeps her voice low, making sure her father doesn't overhear.>\n\nMy friends are goin' out to play down where de shade lilies grow, but I'm supposed to do a buncha borin' apothecary stuff.\n\nPapa wants me to collect some plants to make salves and balms we use for healin'. I asked if it could wait and he said no.\n\nWhat if... you helped me out? Just dis once, pleeease?", progress = "Did you get all of dem?", completion = "All in perfect condition!\n\nMaybe you should be de apprentice instead.", objectives = "Collect 15 Pristine Shade Lilies and 8 Dragonhawk Fern Fronds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93050] = { id = 93050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Altar History", description = "De altars need to be infused with de power of de loas every so often.\n\nI'm not as spry as I used to be and de altars are all spread out.\n\nHelp an old shaman out, eh? I'll give you my totem to channel de loas' power into de altars.\n\nAnd maybe you can learn a thing or two from de other acolytes and myself in de process.", progress = "I just need to take a little breather here.\n\nDon't go worryin' about me, now. Keep focused on the task at hand, eh?", completion = "My days of combat are behind me, but I'm glad to be helpin' out around de village.", objectives = "Empower the 4 Loa Altars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93051] = { id = 93051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Exam", description = "My trainin' is almost complete!\n\nMy commander says I need to prove myself against a strong fighter before she can recommend me for combat.\n\nBut I've been strugglin' to find someone willin' to spar with me after... uh, after what happened de last time...\n\nYou look capable. And intimidatin'. Mind helpin' me out here?\n\nAnd no goin' easy on me, yes? I can take it.", progress = "Do not pull even a single punch. De boy must succeed or fail on his own.\n\nIf he's not ready, you will be doin' him no favors sendin' him into the fray unprepared.", completion = "You fought well.\n\nYour own strength proved Dar'rak can hold his own against warriors far stronger than himself.\n\nI never expected him to beat you, {name}. But de fact that he still breathes is an impressive enough feat, hm?", objectives = "Spar Dar'rak for his final exam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93055] = { id = 93055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extracurriculars", progress = "Back so soon? Perhaps I miscalculated how long you would spend procrastinating.", completion = "Hopefully this diversion has been enlightening.", objectives = "Speak with Khadgar in Dalaran and Eternus at the Infinite Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93056] = { id = 93056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Alacrity", completion = "Yes, now you are prepared.", objectives = "Reach level 70.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93057] = { id = 93057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A House For You", description = "<A glowing parchment appears in front of you with the symbol of a home in front of it.>\n\nGreetings, {name}!\n\nHave you ever wanted to own a home? Have a place to call your own? Now you can!\n\nJoin us in Founder's Point, the new Housing Neighborhood. Get your very own slice of Azeroth!This quest line will unlock:", objectives = "Travel to your capital city's portal room to find a portal to a neighborhood.\n\nYou can also travel to a housing neighborhood from the housing Dashboard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
