quests[93148] = { id = 93148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nAcross gentle falls.\nOcean breeze meets the bounty.\nEast end of the bridge.\n\nGood luck!", progress = "You found the treasure!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93149] = { id = 93149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nSmugglers scheme above.\nTortollans tend bar below.\nSearch through the seaweed.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93150] = { id = 93150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nA secret beast den.\nHidden behind narrow falls.\nSearch the oasis.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93151] = { id = 93151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nThe fire never ends.\nGather for sorrow or mirth.\nSearch behind the fuel.\n\nGood luck!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93152] = { id = 93152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decor Treasure Hunt", description = "Are you ready for today's challenge? I've hidden a piece from my collection here in the neighborhood. To find it, you must merely solve this simple riddle:\n\nLife stirs from dry soil.\nCamp where fishers may take rest.\nFire warms the treasure.\n\nGood luck!", progress = "You found the treasure!", completion = "Well done!", objectives = "Solve the riddle and find the treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93178] = { id = 93178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Quiet Walk Interrupted", description = "It is de hash'ura! De favored of our wily loa! Maybe you can help...\n\nMy father, Oban, is ill and I have been givin' him all my attention.\n\nWhen I turned my back an hour ago, my daughter, Kanza, had run off!\n\nI searched de village, but I can't go further and leave my father behind.\n\nPlease, find where she went? She can be on her own, but she's a sensitive girl, and I don't want her goin' far.\n\nDat fool boy Haz'kel wouldn't come down, but he may have seen her leave. Ask him first.", progress = "I'm so worried about Kanza!\n\nShe shouldn't be on her own.", completion = "What was she doin' out past de log bridge? I told her not to go there.\n\nAnd with my basket and our best tea kettle?\n\nOh... oh, no. She wouldn't! And alone?", objectives = "Help Nerunda find Kanza's whereabouts in Zul'Aman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93179] = { id = 93179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Childlike Devotion", description = "She's goin' to Filo's shrine. She's too old for dat. She's almost thirteen--an adult.\n\nFilo is de Loa of Childhood and protects children. Parents pray to Filo for healthy children.\n\nIt is even said if a child dies, Filo waits with a child in de afterlife until their parents claim dem.\n\nDat is superstition, but dat's why she's goin'.\n\nWe lost her twin, Janaka. She must think she's with Filo.\n\nThe way to Filo's shrine is dangerous, and dat loa won't speak to her. Do what you can to bring her home!", progress = "<Kanza eyes you uncertainly.>", completion = "<You do not want to take the child back by force, but perhaps you can persuade her by to listen to you by helping her with what she is trying to accomplish here.\n\nJudging by the items arrayed before Filo's shrine, she is preparing some sort of ritual.\n\nPerhaps if you help her with the ritual, she may go with you--or go home on her own.>", objectives = "Find Kanza at the Shrine of Filo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93180] = { id = 93180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrine Preparations", description = "<Kanza makes no sound but briefly meets your gaze. She points off toward the hot spring pools.\n\nMaybe she wants you to do something there?>", progress = "<Kanza shifts her weight from foot to foot, swaying impatiently.>", completion = "<Kanza claps and jumps up and down excitedly.\n\nBut she pulls at your sleeve and makes an arcing motion with her hand, pointing into the far distance.\n\nThere is something else she wants you to do.>", objectives = "Follow Kanza and help her by killing 4 Stinger Matriarchs, 6 Stinger Hatchlings, and by collecting 20 Thorncaps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93181] = { id = 93181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple and a Teapot", description = "<Kanza is dancing with excitement.\n\nShe holds her small hand with one finger up.\n\nOne last thing to do.\n\nYou must almost be ready for the ritual to summon Filo--if that is indeed what she is asking for your help to do.\n\nShe fishes in her tunic for something and presents an object to you: the broken handle of a teapot, presumably from the one she dropped on the way here.\n\nPerhaps she needs a substitute?>", progress = "<Kanza looks nervous and expectant.>", completion = "I had to see her.\n\nJust one more time.", objectives = "Buy a teapot from a vendor in nearby Camp Stonewash and help Kanza start the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93182] = { id = 93182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Healing Homeward", description = "I will go home.", completion = "I don't know what you did or what de loa did, but I got my Kanza back and more.\n\nShe is talkin' again like she used to. More even. She never talked a lot.\n\nAnd I'm goin' to make her a place where she feels safe to keep talkin' to me.", objectives = "Return to Nerunda in Witherbark Bluffs and check if Kanza returned home.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93200] = { id = 93200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Handful of Voidlight Marl", objectives = "We're grateful for your help. Take these supplies as a gesture of thanks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93257] = { id = 93257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revantusk at Risk", description = "Fishers of de forest tribes constantly talk to each other about our hauls, and none are more legendary than de river-walking Revantusk and their crabs! But...\n\nI've heard they've fallen on hard times. First, de Twilight's Blade ransacked their city. Now, their cages aren't bringing in enough meat for de refugees.\n\nDe Revantusk have a new head river-walker, Kahanea, who could use an extra set of hands in taking care of dis crab problem.\n\nYou up to de task, outsider?", completion = "So word of our famine has spread?\n\n<Kahanea grimaces.>\n\nThere is no denying it.", objectives = "Find Kahanea in Nalorakk's Prowl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93258] = { id = 93258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crab Clues", description = "De rumors are true. No matter what we try, we aren't netting as many crabs as before. And de ones we do catch taste wrong, even making some of my people sick!\n\nI succeeded my mother's position as head river-walker after losing her to de Twilight's Blade. Dealing with dis famine, my new duties, and my grief... It's so much for me to bear.\n\nDis is de area where we first noticed an issue with our crabs. Can you investigate for me while I make more traps?", progress = "I must make dis right--for my people. For my mother. I wish she could give us guidance.", completion = "Void-tainted bodies and baskets? And some crazed crabs ambushed you? Dis is getting worse!\n\nNak'tek found de Void polluting baskets upriver, just like what you found down here along de lakeshore. De Void ties all of our clues together! Let's follow that lead.", objectives = "Investigate the lakeshore for causes of the food shortage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93259] = { id = 93259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clobbering Crawlers", description = "While I continue to scout de area for causes of dis famine, please harvest crab meat for our refugees. Their hunger only gets worse as our investigation goes on.\n\nSince de traps aren't working, you have to hunt those crabs yourself and get food straight from de source!\n\nMake sure you're getting healthy meat, though. I'm worried about some of those crabs being infected with de Void.", progress = "My people have been through so much. Everyone deserves a warm home to return to, and a hearty meal to restore their strength and spirit.", completion = "Dis is more meat than we've seen in a week! My people will be grateful for an actual meal. You have my gratitude.", objectives = "Harvest 10 pieces of Mouthwatering Crab Meat from the crabs upriver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93260] = { id = 93260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caging Crawlers", description = "Our traps being mucked up with de Void would explain why we've been catching fewer crabs! And why some of de crabs have made our people sick.\n\nPlease clean our traps upriver! Based on Nak'tek's report, de infected crabs sound dangerous... so be careful approaching those traps.\n\nYou can find de baskets nestled among de sticks or by bases of waterfalls--dey provide a natural disguise! Crabs are easily tricked dat way.", progress = "Were you able to clean any of de traps? Or find a source of de filth gumming them up?", completion = "Those shards you found must've caused de Void pollution clogging our traps. I'm glad you removed them! De river looks much cleaner, and our trap count is back to normal... for now.\n\nMay these baskets receive Nalorakk's blessing and provide for de Revantusk once more.", objectives = "Clean 6 Crab Traps upriver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93261] = { id = 93261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Crab of Unusual Size", description = "I followed de Void pollution trail upriver and spotted a beast before it ran off to its cave: an enormous, void-addled crab. It was shedding those shards dat were polluting de river!\n\nAs long as dis beast lives, it'll keep spreading pollution and infecting crabs with de Void. It must be stopped!\n\nI'd stay and fight, but I must warn everyone at de Overlook.\n\nPlease, {name}. Slay dat crab and remove de source of its corruption before it can hurt more of my people!", progress = "I don't know if de Twilight's Blade created dat beast or not, but it needs to GO!", completion = "So de Twilight's Blade hasn't just hurt de Revantusk, but our wildlife as well? We must keep an eye on de cultists and protect Nalorakk's Prowl from their pollution!\n\nDe health of our people and our crabs is my top priority. Seeing my people starve under my watch filled me with rage, and guilt... like I was tarnishing my mother's memory as head river-walker.\n\nYour aid has helped me become de leader my river-walkers need.\n\nThank you, {name}. You're forever welcome with de Revantusk.", objectives = "Defeat the Mania-Crab and remove the source of its corruption.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93262] = { id = 93262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endeavor" }
