quests[93372] = { id = 93372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Shadow Enclave", description = "The perfidious cultists of the Twilight's Blade have infiltrated Eversong and set up their horrid operations in a nearby cavern. Clear them out before they spread any further!", completion = "Good job and good riddance.", objectives = "Complete the Shadow Enclave delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
