quests[93382] = { id = 93382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pardon the Interruption", description = "{name}! Glad to see you. The defenders in the fortress could use your help.\n\nOne of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on.\n\nShe needs the help of someone who can properly disrupt the robot's attacks so it can be repaired.\n\nDo you have a moment to help?", completion = "Great work! Now I should have time to fix whatever bug actually caused this in the first place.\n\nMaybe I can just say it's a feature and call it a day!", objectives = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 3 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93384] = { id = 93384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Collegiate Calamity", description = "The arcane tome, clearly agitated by something, bears the mark of Silvermoon's Thalassian University.\n\nIt could be worth investigating.", progress = "Is something amiss at the university?", completion = "Thank you, {name}. The situation was hardly conducive to study.", objectives = "Complete the Collegiate Calamity delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93385] = { id = 93385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: The Darkway", description = "Remnants of the Twilights Blade scurry like rats through the Arcway tunnels beneath Suramar.\n\nExterminate the vermin before they spread.", objectives = "Complete The Darkway delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93386] = { id = 93386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Parhelion Plaza", description = "Adventurers! Quel'Danas is once more under attack by the Void, and any who are able to provide assistance should head to the battlements of Parhelion Plaza to help stem the tide.", objectives = "Complete the Parhelion Plaza delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93396] = { id = 93396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bursting at the Seams", description = "Veraan... alive...\n\n<Kifaan shakes his head in disbelief.>\n\nI've spent countless hours running this moment through my head, but now that it's here, I find myself grasping for words...\n\nThe Shadowguard attempted to raise Dimensius to power... they've sworn fealty to Xal'atath as she wages war on worlds. Am I supposed to just... pretend none of that happened? Is THAT what my oaths to family require?\n\nAnd what of Veraan? Does she regret her involvement?\n\nI should check on her.", completion = "I've been focusing on my own feelings so much that I never stopped to think about how Veraan might feel.\n\nI may not have fared any better had they pumped ME full of Void.", objectives = "Help Kifaan check on his sister's well-being.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93397] = { id = 93397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnawing Hunger" }
quests[93409] = { id = 93409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Atal'Aman", description = "<The fallen scout's body bears terrible wounds, but still clutches tightly to a report detailing an immanent Vilebranch attack on Atal'Aman.>", completion = "Good. They should learn to stay in their holes.", objectives = "Complete the Atal'Aman delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93410] = { id = 93410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Twilight Crypts", description = "The ancient Amani crypts near the Broken Throne have been overrun.\n\nClear them of interlopers before the dead within can be defiled further.", completion = "One day Zul'Aman will be free of their taint.", objectives = "Complete the Twilight Crypts delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93416] = { id = 93416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: The Gulf of Memory", description = "Rumors of disturbances in the Gulf of Memory have begun to spread.\n\nDeal with the issue before it can take root.", completion = "Thank you, {name}, for nipping that in the bud.", objectives = "Complete the Gulf of Memory delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93421] = { id = 93421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: The Grudge Pit", description = "<This moldy hanging has been crudely painted over to depict one fungarian hitting another with what looks to be a chair.>\n\nSee big fight. Best fight!\n\nGrudge Pit. Be there!", completion = "Good fight? Yes.\n\nBest fight? Maybe!", objectives = "Complete The Grudge Pit delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93424] = { id = 93424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of War: Zul'Aman", description = "There's unknown danger out in Zul'Aman.\n\nGet out there and clear things up!", objectives = "Collect 100 Sparks of War in Zul'Aman, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93425] = { id = 93425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparks of War: Harandar", description = "Powerful creatures have grown through the lands across Harandar. Go look into it.", progress = "There's more to explore.", completion = "That was a tremdenous effort - much thanks.", objectives = "Collect 100 Sparks of War in Harandar, while in War Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93427] = { id = 93427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Sunkiller Sanctum", description = "<A note is pinned to the slain voidwalker.>\n\nSunkiller Sanctum is a den of Xal'atath's most pathetic sycophants.\n\nI encourage any mercenaries, adventurers, or general do-gooders who happen upon this bounty to pay it a visit and dispense the justice you are all so happy to talk on and on about.\n\n - Perodius", completion = "Your fee, {class}.\n\nThat will teach them to rebuff a perfectly good bribe in the future.", objectives = "Complete the Sunkiller Sanctum delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93428] = { id = 93428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver's Call: Shadowguard Point", description = "Witness the fates of those who bend their neck to Xal'atath.\n\nI issue a challenge to any creature of Void or flesh. Pursue the nearby ethereals and dispatch anyone who serves the so-called Harbinger.\n\n - Perodius", completion = "For services rendered.\n\nIf only all mortals were as helpful as you.", objectives = "Complete the Shadowguard Point delve on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93432] = { id = 93432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swords to Plowshares", description = "First Mor'duun and the Blade ambush Atal'Aman. Now it's overrun by these \"echoes...\"\n\nAt least, that's what Doru calls them: echoes. All I see are ghosts of a bloodier time. And like those days, no matter how many we cut through, they never stop swarming in.\n\nGet out there and see for yourself. Bring de echoes' remains as well. Doru wants to study what dey are and how dey work.", progress = "It's like a dream you can't wake from.", completion = "See? An endless ocean.\n\nPerhaps Doru will learn something from de ashes.", objectives = "Collect 20 Raider Ash Remains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93433] = { id = 93433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrine, Sealed, Delivered", description = "Curse de echoes. \n\nCurse Zul'jin, and Mor'duun, and dat snake Malacrass too.\n\nThey only cause more mess for de livin' to clean up.\n\nListen, hash'ura. I need you to deliver supplies to each of de shrines in de city. We've packaged food, water, bandages, and reagents to keep their barriers at full strength.\n\nAsk about their status as well. Though safe, they all likely feel boxed in.", completion = "Barriers holdin'? Good.\n\nNow we can focus on de offensive.", objectives = "Deliver supplies to the Elders of the four Loa Shrines: Elder Shimarra, Eagletender Rhyd, Elder Thak, and Elder Vu'lona.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93435] = { id = 93435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Four Instigators", description = "De scouts report seein' a few unique faces among de echoes. I felt old angers rising when I heard de names.\n\nDey were not honorable fighters for us to challenge ourselves against, such as yourself. They were vermin--greedy opportunists that drove legions of connivin' adventurers to rob us of our possessions, our treasures, and... our tusks.\n\nSlayin' de echoes of these key figures should reduce de number of echoes appearin'.\n\nAnd it will make me grin to know they've fallen.", completion = "I admit it, {name}: knowin' you have slain de instigators brings warmth to my old bones.\n\nDoes dat lower your opinion of me?", objectives = "Slay the echoes of Prigmon, Zungam, Budd Nedreck, and Harrison Jones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93436] = { id = 93436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hex the Innocent, Disrupt the Guilty", description = "I will study de ashes you acquired, but we can get dis situation under control by means other than de axe.\n\nYou must disrupt de battlefield, hash'ura. De echoes believe dey're in de midst of a decades-old battle, so we must target de support dey relied on back then.\n\nPoison de feasts dey find respite at, hex their disrespectful civilian allies, and sabotage dat chest they seem so keen on lootin'!", completion = "De echoes are runnin' from de battlefield like scared hogs because of your work!", objectives = "Poison 3 Raider's Feasts, hex 7 Civilians, and sabotage the Warlord's Chest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93437] = { id = 93437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Their Own Blood", description = "After studying de ashes, Doru believes we can only fight with de past using weapons of de past.\n\nI cannot ask this of any Amani. Or Witherbark, Revantusk, or Shadowpine. Ya presence with us in these times must be fate... because we could only make this request to an outsider.\n\nYa must inhabit a soul of de profane ones: those that accepted Malacrass's vile bargain and consumed loa power during de era of Zul'jin.\n\nReturn to de shrine of de profane one ya wish to merge with.\n\nAncestors forgive us...", completion = "Thank you, hash'ura. Truly.\n\nThe battle against de echoes will continue. However, it would seem dey cannot return after being slain now dat their leader has been dealt with.\n\nMemories stirred my blood these last few days. Now we can all rest. Perhaps even move on?\n\nBah! It's just de ravin' of an old warrior. Do not mind me. \n\nSimply consider myself in your debt.", objectives = "Become one of the four Loa Avatars.\n\nSlay Raiding Echoes in Atal'Aman, and defeat the Raid Leader upon the Warlord's Stair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93438] = { id = 93438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Precision Excision" }
quests[93440] = { id = 93440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Personal History", description = "With Mor'duun slain and de Twilight's Blade defeated, my people want to return to Atal'Aman.\n\nIt should be a moment of great celebration but... somethin' unexpected is barrin' our way.\n\nSeek out Torundo and Elder Doru. Dey are supportin' de resettlement. They'll know how best to use your talents.\n\nPrepare yourself, hash'ura, and do not hesitate to defend Atal'Aman no matter who you meet there.", completion = "Zul'jarra sent you, hash'ura?\n\nHeh. She must be tired of waitin' on us to make headway.", objectives = "Speak with Torundo the Grizzled in Atal'Aman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93452] = { id = 93452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retrieved Crumpled Present", description = "<It seems the minions of the Greench have fled, leaving behind a small mangled, but still salvageable present.\n\nPerhaps one of the Winter Festivities planners would be able to help return it to the original intended recipient.>", sourceObjective = "Talk to Joanna Copperpinch in the Razorwind Shores neighborhood.", sourceObjectiveStatus = "unverified-source-field" }
quests[93453] = { id = 93453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grave Concern", description = "Dearly Departed,\n\nHaving just tasted the bitter sting of mortality, there seems no better time to discuss with you the oft ignored subject of death and memorialization. Of what you leave behind in a real, physical sense.\n\nLeave discussion of love and other such frivolities to the philosophers and dandies. I speak of cold, hard stone and the deeds carved upon it.\n\nFind me in Silvermoon.", progress = "Have you made your selection?", completion = "Excellent. Feel free to make new arrangements whenever you would like.\n\nI, like death, am a patient man.", objectives = "Meet with Nelthius Shadestone in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
