quests[93566] = { id = 93566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Amani Tribe", description = "You continue to prove yourself to de Amani and de other forest tribes alike.\n\nSpeak to me when next you are in Amani'Zar. Zul'jarra asked me to put a few items aside as our way of sayin' thanks.", sourceObjective = "Speak with Magovu in Amani'Zar Village.", sourceObjectiveStatus = "unverified-source-field" }
