quests[93571] = { id = 93571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dispersing Shadows" }
quests[93575] = { id = 93575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maisara Caverns: Maisara Hungers", description = "I will not leave my people to die to de Vilebranch's dark rituals. We must go after dem.\n\nThe heart of Maisara Caverns is where de Vilebranch keep their secrets. I expect dis to be a bloody trip. We will have to face de ugliness of the Vilebranch greed, and what it is costin' all of us.\n\nWe must discover what purpose they have for my stolen kin. If any still be alive. I will be dere to aid you... but bring a fierce party of warriors. We will need it.", progress = "Gather your warparty. I will see you in Maisara Caverns.", completion = "Dat be a dark business indeed. So many lost, to such a terrible fate!\n\nBut no more, thanks to you. You have de Witherbark's gratitude... and mine.", objectives = "Complete the Maisara Caverns dungeon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
