quests[93581] = { id = 93581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against Overwhelming Odds", description = "Friends - I sense some troubles out there. There's foes out there that harbor grudges and are looking for a fight. Join others and show those looking for a battle who is mighty.", objectives = "Slay 25 Level 90 Horde anywhere within Midnight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93582] = { id = 93582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against Overwhelming Odds", description = "Friends - I sense some troubles out there. There's foes out there that harbor grudges and are looking for a fight. Join others and show those looking for a battle who is mighty.", objectives = "Slay 25 Level 90 Alliance anywhere within Midnight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93586] = { id = 93586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conditional - Multiple Objectives, Non Sequenced", description = "I be sent out here ta prove dat I can be an amani warrior.\n\nDis trial needs me ta collect as many trophies from dese gnarldin as possible. \n\nDe two of us should work together! I be helpin' you get recognized as an amani warrior, yeah?\n\nJust go out dere and get as many trophies from de gnarldin as possible. \n\nI be stayin' behind ta watch our backs, eh?", objectives = "Recover 1 trophies from gnarldin and their allies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93599] = { id = 93599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Very Best", description = "Even the smallest amongst us must play their part. That includes our little friends.\n\nIf you would strengthen both their prowess and your bond, challenge others. Only the fittest will survive.You will be able to choose one of these rewards:", objectives = "Defeat 5 players through Find Battle with a team of level 25 pets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93640] = { id = 93640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish Finagling", description = "I had wanted to bring the tea set home to my wife to surprise her...\n\nBut that won't make up for me not bringing home any fish for supper.\n\nHm. I'll make a deal with you, {class}. I've been standing here all day trying to catch some fish for my beautiful wife to cook for us. But the crabs keep stealing my catch--and my bait! Run them off so I can catch and keep some fish, and I will give you this teapot." }
quests[93641] = { id = 93641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against Overwhelming Odds", description = "Friends - I sense some troubles out there. There's foes out there that harbor grudges and are looking for a fight. Join others and show those looking for a battle who is mighty.", objectives = "Slay 25 Level 90 Horde anywhere within Midnight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93642] = { id = 93642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against Overwhelming Odds", description = "Friends - I sense some troubles out there. There's foes out there that harbor grudges and are looking for a fight. Join others and show those looking for a battle who is mighty.", objectives = "Slay 25 Level 90 Alliance anywhere within Midnight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93647] = { id = 93647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumber For You", objectives = "Ye look like someone who could learn the art of bein' a lumberjack!\n\nI can teach ye real quick how to identify which trees are prime for gettin' some lumber.\n\nLumber has all sorts of uses when crafting stuff for yer house. Or other folks' houses, if you care to sell your goods. Might want to visit some o' your old craftin' teachers to brush up while you're at it. They've got some new things to teach, I'd wager!\n\nSo get what ye can and see what ye can make of it!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93651] = { id = 93651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blinding Vale: Lightbloom Roots", description = "We have traced Ruia's flight through the Rootways. As we suspected, he has sought refuge deep within The Blinding Vale, where the Lightbloom first took root within Harandar.\n\nWith Alndust empowering our command of life, we are able to keep the Lightbloom from spreading uncontrolled. But we will run out of Alndust long before Ruia runs out of patience.\n\nRuia is wise and powerful. But his actions in Eversong prove that his conviction has grown into an uncontrollable fanaticism. He must be stopped.", completion = "So it is done, then.\n\nRuia's demise is a tragedy. You never knew him as such, but he was once a man of honor and conviction. To think that the Light would blind him so completely to the folly of his ambitions...\n\nIn the end, he thought he was doing what was best for Harandar. I can only hope his soul finds both peace and forgiveness, as it seeks Aln'hara in death.", objectives = "Complete The Blinding Vale dungeon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93667] = { id = 93667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camp Stonewash", description = "You're not the first strange thing I've seen today.\n\n<Scout Zel'kanra shakes her head.>\n\nSaw a big, shelled creature along the path to Jan'Alor. Amaxi took a bunch of scouts and went after it.\n\nThey've been gone a while. Think you could check in on them?", completion = "Who are you? What are you doing here?\n\n<Amaxi tenses, but relaxes after a moment.>\n\nShadebasin sent you. Yes, we're fine. But these tortollan should not be here!", objectives = "Find Amaxi outside Camp Stonewash in Zul'Aman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93683] = { id = 93683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conditional Objectives - Singular", description = "{name}! Glad to see you. The defenders in the fortress could use your help.\n\nOne of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on.\n\nShe needs the help of someone who can properly disrupt the robot's attacks so it can be repaired.\n\nDo you have a moment to help?", objectives = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93687] = { id = 93687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taste True Power", objectives = "This quest line will unlock:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93690] = { id = 93690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alchemy Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", progress = "Bring back proof of completed orders and I'll see that you're adequately compensated.", completion = "You have our gratitude, {class}. Silvermoon stands stronger thanks to your skills.", objectives = "Fill Alchemy Crafting Orders for the Artisan's Consortium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93691] = { id = 93691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blacksmithing Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", progress = "Bring back proof of completed orders and I'll see that you're adequately compensate", completion = "You have our gratitude, {class}. Silvermoon stands stronger thanks to your skills.", objectives = "Fill Blacksmithing Crafting Orders for the Artisan's Consortium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93692] = { id = 93692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Engineering Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", completion = "You have our gratitude, {class}. Silvermoon stands stronger thanks to your skills.", objectives = "Fill Engineering Crafting Orders for the Artisan's Consortium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93693] = { id = 93693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inscription Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", completion = "You have our gratitude, {class}. Silvermoon stands stronger thanks to your skills.", objectives = "Fill Inscription Crafting Orders for the Artisan's Consortium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93694] = { id = 93694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jewelcrafting Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", progress = "Bring back proof of completed orders and I'll see that you're adequately compensated.", completion = "You have our gratitude, {class}. Silvermoon stands stronger thanks to your skills.", objectives = "Fill Jewelcrafting Crafting Orders for the Artisan's Consortium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93695] = { id = 93695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leatherworking Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", completion = "You have our gratitude, {class}. Silvermoon stands stronger thanks to your skills.", objectives = "Fill Leatherworking Crafting Orders for the Artisan's Consortium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93696] = { id = 93696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tailoring Services Requested", description = "Welcome back, {class}. If you're still interested in working with the Artisan's Consortium, we would value your aid. We need highly skilled artisans to craft supplies for the war effort.\n\nIf your work meets Silvermoon's high standards of quality, please fill any public crafting orders you find on the board. You can also fill orders for yourself, your guildmates, or private patrons.\n\nBring back proof of completed orders and I'll see that you're adequately compensated.", progress = "Bring back proof of completed orders and I'll see that you're adequately compensated.", completion = "You have our gratitude, {class}. Silvermoon stands stronger thanks to your skills.", objectives = "Fill Tailoring Crafting Orders for the Artisan's Consortium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93698] = { id = 93698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splintered Radiance", description = "When captured at just the right moment, the power exuding from an object can be crystallized into splinters of raw magical energy. The result is dazzling, like beams of sunlight splitting as they stream through a window.\n\nBring me some of these shards. My work cannot continue without them.", progress = "A few shards should be sufficient.", completion = "Oh, they glow with such wonderful power! These should do nicely.", objectives = "Collect 10 Radiant Shards and deliver it to Dolothos in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93699] = { id = 93699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ray of Sunlight", description = "There is great magic in the dawn. It illuminates and awakens all it falls upon, rousing the land to action. It is potential in its purest form.\n\nAs enchanters, we can crystallize that potential. Bring a parcel of the dawn to me.", objectives = "Collect 1 Dawn Crystal and deliver it to Dolothos in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93703] = { id = 93703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sin'dorei Vices", description = "While most of our harvests supply the scribes and alchemists in the city, we do occasionally receive orders from the public.\n\nLord Saltheril is one of our most prolific customers. He has an estate in western Eversong that he keeps well-supplied with offerings for guests at his soirees.\n\nHe has requested a large quantity of mana lilies and sanguithorn this week. Could you help us fulfill the order?", progress = "Lord Saltheril's business is always welcome, even if a bit eccentric.", completion = "Excellent. With your help and what we already have in stock, this should cover his order.", objectives = "Collect 5 Mana Lilies and 2 Sanguithorn and deliver it to Botanist Nathera in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93706] = { id = 93706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressive Tin-dencies", description = "There's been an influx of newly recruited soldiers lately. Marvelous fighters in the making, but a little too enthusiastic. They've already done a number on the stock of training weapons.\n\nWe usually make training weapons out of tin or other soft metals. They keep the recruits from doing real damage to the training dummies or each other, but they don't last long.\n\nWe'll need a lot more tin than what we have in stock to keep up. Bring us some more!", objectives = "Collect 10 Umbral Tin Ore and deliver it to Belil in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93708] = { id = 93708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conductive Metals", description = "Our arcane constructs might look purely magical, but there's quite a bit of advanced wiring going on beneath the surface. Silvermoon's engineers truly are spell-workers in their own right.\n\nThey've been ramping up production lately to help fortify our defenses. Naturally, they look to us for supplies. I have most of the materials they ordered, but I'm low on tin and silver.\n\nCould you help me fulfill the order?", progress = "Tin and silver are both remarkably conductive. I could elaborate, if you have a few hours?", completion = "Ah, yes. This quantity should be sufficient. I'll have it packaged up for the engineers.", objectives = "Collect 5 Umbral Tin Ore and 5 Brilliant Silver Ore and deliver it to Belil in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93712] = { id = 93712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Style and Skill", description = "In battle, appearances are nearly as important as raw skill. If you can intimidate your foe before you've even drawn your sword, you're already that much closer to victory.\n\nOur fletchers take this a step further and insist that beautiful feathers make our Farstriders' arrows do more damage. I'm... not certain about that, but I can appreciate the aesthetic.\n\nHere's a list of what they need for this week's batch of arrows. Supply whatever you can and I'll handle the rest.", progress = "You can ignore the note about whether the feathers should be crimson or scarlet.", completion = "Ah, these should make excellent arrows.", objectives = "Collect 5 Carving Canines and 5 Peerless Plumage and deliver it to Tyn in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93714] = { id = 93714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minor Scales", description = "A well-made suit of scalemail is a sight to behold. It requires quite a bit of patience and attention to fine detail, but Silvermoon's leatherworkers are masters of the craft.\n\nIf you happen to hunt any scaled beasts, we could use those materials. A large quantity of smaller sized ones, if you could--they layer more nicely in the armor.", objectives = "Collect 20 Void-Tempered Scales and deliver it to Tyn in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93723] = { id = 93723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafters Needed", description = "Greetings. Come to lend a hand?\n\nThe war effort has been taxing on Silvermoon's resources. We need to keep our soldiers armed and supplied, but even our seasoned crafters have been overwhelmed. To keep up with demand, we have struck a deal with the Artisan's Consortium.\n\nIf you have your own skills to offer, speak to Mar'nah. She can help you view and place crafting orders.", progress = "Have you talked to Mar'nah?", completion = "Fulfilling these work orders is imperative to the war effort. Your services are greatly appreciated.", objectives = "Talk to Mar'nah in the Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93724] = { id = 93724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafting Orders: Alchemy", description = "Ah, you're an alchemist?\n\nYou should speak with Camberon. He's a skilled alchemist who runs a shop here in Silvermoon.\n\nCamberon has a work table at his shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek him out and see what work is available for you.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "It is ever an honor to meet a fellow alchemist. Clean up your spills and we'll be well on our way to friendship.", objectives = "Find Camberon in the Bazaar and use his Alchemist's Lab Bench.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93726] = { id = 93726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafting Orders: Blacksmithing", description = "Ah, you're a blacksmith?\n\nYou should speak with Bemarrin. He's a skilled blacksmith who runs a shop here in Silvermoon.\n\nBemarrin has a work table at his shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek him out and see what work is available for you.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "A pleasure meeting you. But if you misplace my good pair of tongs, I'll have you thrown right out.", objectives = "Find Bemarrin in the Bazaar and use his Blacksmith's Table.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93727] = { id = 93727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafting Orders: Engineering", description = "Ah, you're an engineer?\n\nYou should speak with Danwe. She's a skilled engineer who runs a shop here in Silvermoon.\n\nDanwe has a work table at her shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek her out and see what work is available for you.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "Good engineers are hard to come by. Get a handle on those arcane constructs and you'll be drowning in work from the Magisters alone.", objectives = "Find Danwe in the Bazaar and use her Tinker's Workbench.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93728] = { id = 93728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafting Orders: Inscription", description = "Ah, you're a scribe?\n\nYou should speak with Zantasia. She's a skilled scribe who runs a shop here in Silvermoon.\n\nZantasia has a work table at her shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek her out and see what work is available for you.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "You have a fine and steady hand, {name}. I look forward to seeing what you can create.", objectives = "Find Zantasia in the Bazaar and use her Scribe's Drafting Table.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93729] = { id = 93729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafting Orders: Jewelcrafting", description = "Ah, you're a jewelcrafter?\n\nYou should speak with Amin. He's a skilled alchemist who runs a shop here in Silvermoon.\n\nAmin has a work table at his shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek him out and see what work is available for you.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "It seems like every set of armor these days needs a dozen gems inlaid. Not that I am complaining, especially not with your aid whittling down the work orders.", objectives = "Find Amin in the Bazaar and use his Jeweler's Bench.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93730] = { id = 93730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafting Orders: Tailoring", description = "Ah, you're a tailor?\n\nYou should speak with Galana. She's a skilled tailor who runs a shop here in Silvermoon.\n\nGalana has a work table at her shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek her out and see what work is available for you.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "Fine spellcasters demand fine robes, but their high standards keep our skills sharp. Perhaps you and I can share techniques.", objectives = "Find Galana in the Bazaar and use her Tailor's Work Table.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93731] = { id = 93731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crafting Orders: Leatherworking", description = "Ah, you're a leatherworker?\n\nYou should speak with Talmar. He's a skilled leatherworker who runs a shop here in Silvermoon.\n\nTalmar has a work table at his shop where you can review, craft, and deliver work orders from public lists and personal contacts like friends and guildmates. If you're lucky, you might come across an order from a renowned person offering a special commission.\n\nSeek him out and see what work is available for you.", progress = "The work orders never stop piling up. I'd be glad to have some extra help.", completion = "The beasts of Quel'thalas have the finest leather you will ever work with. I look forward to seeing what you make of it.", objectives = "Find Talmar in the Bazaar and use his Leatherworker's Tool Bench.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93734] = { id = 93734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precious Trinkets", description = "Finally we get to see what treasures Groffa was hoarding.\n\n<Furgh's eyes go black as he looks at the bag. The drool on his jowls turns to foam and his claws dig into the sides of the bag as his grip on it tightens.>\n\nMaybe the loa speaker's gifts aren't so bad. We should not be so hasty. I'll take a look. You watch and keep me safe.", progress = "Whatever Groffa had is bad. Right?", completion = "You didn't need to burn my things...", objectives = "Keep Furgh safe and investigate the treasures.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93744] = { id = 93744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unity Against the Void" }
quests[93745] = { id = 93745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Har'athir, Village of Memory", description = "You have been permitted to range about beneath our Goddess' light. But that doesn't mean we trust you out of hand.\n\nIf you wish to prove yourself a friend to the haranir, make yourself useful in Har'athir. It is there that we make the paints for our murals and watch over the newest roots to seek the Goddess' light.", completion = "So you survived your meeting with the elders. I am surprised, but also pleased.\n\nYou aided the children of Har'athir without hesitation. For that, I welcome you and offer you the hospitality of Amirdrassil's roots.", objectives = "Meet Rootwarden Ku'paal in Har'athir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93752] = { id = 93752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murder Row", description = "I've always disagreed with Lor'themar about the existence of Murder Row. But I guess like any forest, a city should and will have its secrets.\n\nThough recently, Lor'themar has expressed concern about rising fel activity in the area. With the majority of Silvermoon's watch on the Voidstorm, many folks are testing boundaries, taking advantage, making a play for power...\n\nYou have my permission to investigate and crush any such illegal activities.", sourceObjective = "Complete the Murder Row dungeon on any difficulty.", sourceObjectiveStatus = "unverified-source-field" }
quests[93753] = { id = 93753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magisters' Terrace", description = "Powerful monsters of the void have taken over Magister's Terrace! These halls contain untold amounts of knowledge and arcane power. We cannot lose any of it to our enemy.\n\nClear the voidspawns and their masters. You'll likely have to solve the terrace's defenses as well, which are designed to prevent and shutdown unauthorized access at any cost.", progress = "If the Void gains access to Silvermoon's most exclusive repository of magic... Rommath will throw a fit of epic proportions.", completion = "That was a close call. As for Rommath and Umbric, that's a puzzle for another day.", objectives = "Complete the Magisters' Terrace dungeon on any difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93766] = { id = 93766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: World Quests", description = "The Void seeks to divide us, to drive a wedge between kin and kingdom alike. We cannot allow it.\n\nEverywhere I turn, I hear of those struggling--families displaced, defenders overwhelmed, healers stretched thin. No blade nor spell alone will turn this tide, but the strength of many hearts united can.\n\nGo forth and lend your aid where it is needed most.You will learn:", objectives = "Complete World Quests in Midnight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93767] = { id = 93767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Arcantina", description = "The Arcantina welcomes all who seek respite.\n\nStep inside its lively halls, share a brew, and trade stories with friends old and new. \n\nWhere the Void brings chill and silence, here you'll find warmth, laughter, and the spark of fellowship.", completion = "Ah, you've returned. I am glad you allowed yourself that well-earned moment of peace.", objectives = "Visit the Arcantina and have a brew with one of the patrons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93769] = { id = 93769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Housing", description = "A strong community is built not by walls, but by the hands and hearts of those within it. \n\nLend your voice, your time, and your spirit to the neighborhood. Help your fellows, share in their burdens, and take your place as an active part of the home we build together.You will learn:", objectives = "Participate in neighborhood Endeavors and collect Community Coupons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93771] = { id = 93771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Har'kuai, Village of Rain", description = "All waters in Harandar are sacred. They feed the roots of the world and Aln'hara's myriad creations in equal measure. Perhaps none are more spectacular than those that fall from the roots of the tree called Nordrassil.\n\nTo the north, you will find Har'kuai. The rains that fall from the sky there carry a remarkable vitality. If you wish to witness all of Aln'hara's majesties, then a trek to Har'kuai would serve you well.", completion = "I have heard of your travels, outsider. I am Kamari, Rootwarden of Nordrassil.\n\nThe mists of Har'kuai hold many mysteries. I hope you will find them enlightening, during your stay here.", objectives = "Meet Rootwarden Kamari in Har'kuai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93775] = { id = 93775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Har'mara, Village of Balance", description = "Ah! The outsider who saved Har'mara. Word travels fast through Aln'hara's roots. No doubt Elder Hagar was grateful for your aid.\n\nShe would never admit it, but things have been difficult since the roots above her village burned. The rutaani and fungarians each grow bolder in their eccentricities. And the lingering flare-ups on Teldrassil's roots present a constant threat.\n\nIf your travels afford another trip to Har'mara, I do not doubt she would benefit from additional help.", completion = "Ah! {name}. Welcome back. As you can see, our hands are full as ever, here.\n\nI assure you, I have things well in hand. But if you do wish to explore a bit further afield, I am sure some of the others could benefit from your assistance.", objectives = "Return to Hagar in Har'kuai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93776] = { id = 93776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Har'alnor, Village of Twilight", description = "Our efforts in the Blinding Bloom have halted the Lightbloom's encroachment for now. But with Rootwarden Ruia gone, there are scarce few who remain to handle the rest of the village's troubles.\n\nI'm going back to Har'alnor to help out where I can. If you have the time and the inclination, your further assistance would be most appreciated.", completion = "Thank the goddess you returned.\n\nAs you can see, we're still in fairly dire straits here. Though we quelled its spread beneath Shaladrassil's roots, the Lightbloom remains a threat. There are rumors of fungarians acting erratically in Fungara Village. And there is no Rootwarden in Har'alnor to deal with either.\n\nThankfully, we have the next best thing: an intrepid outsider with a habit of helping others.", objectives = "Meet with Hannan in Har'alnor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93782] = { id = 93782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conditional - Multiple Objectives, Sequenced", description = "I be sent out here ta prove dat I can be an amani warrior.\n\nDis trial needs me ta collect as many trophies from dese gnarldin as possible. \n\nDe two of us should work together! I be helpin' you get recognized as an amani warrior, yeah?\n\nJust go out dere and get as many trophies from de gnarldin as possible. \n\nI be stayin' behind ta watch our backs, eh?", objectives = "Recover 1 trophies from gnarldin and their allies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93783] = { id = 93783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conditional - Just One Objective", description = "I be sent out here ta prove dat I can be an amani warrior.\n\nDis trial needs me ta collect as many trophies from dese gnarldin as possible. \n\nDe two of us should work together! I be helpin' you get recognized as an amani warrior, yeah?\n\nJust go out dere and get as many trophies from de gnarldin as possible. \n\nI be stayin' behind ta watch our backs, eh?", objectives = "Recover 1 trophies from gnarldin and their allies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93784] = { id = 93784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gnawing Void of Curiosity", description = "<The artifact crumbles in your hand, leaving only a faint but distinctly ancient arcane footprint. Naleidea Rivergleam will want to hear about this.>", sourceObjective = "Report your discovery to Naleidea Rivergleam in Silvermoon City.", sourceObjectiveStatus = "unverified-source-field" }
quests[93792] = { id = 93792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessings of the Loa", description = "My name is Du'gal. And you are hash'ura.\n\nKinduru has ordered me to train you in de ways of loa worship. Take honor in it. Very few gokinye have earned de right as you have.\n\nBeside me is de Altar of Blessings. You may use it to worship any of our loa, and you shall receive a sliver of power in thanks.\n\nGo ahead now, if ya be so kind.", progress = "De loa are quite generous indeed.", completion = "Ya spirit is flowing with strength!\n\nYou may use de altar as often as ya wish. But ya can only hold one blessing on ya self at a time.", objectives = "Worship at the Altar of Blessings.\n\nGain a blessing by choosing to combine the power of Akil'zon, Halazzi, Jan'alai, or Nalorakk with that of any lesser loa you've formed a bond with.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93801] = { id = 93801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calculated Culling", description = "This pathogen is spreading rapidly among the denizens of the Molt.\n\nA swarm of netherwasp hatched shortly after our arrival. The infection spread throughout the region as they fought over territory. If their numbers continue to grow, they could carry the pathogen to the rest of Voidstorm.\n\n{name}, can I ask you to reduce the number of infected creatures in the Molt?", progress = "This place has such vitality. It's no wonder the pathogen has spread so easily.", completion = "Your efforts and assistance are both noted and appreciated.", objectives = "Cull creatures endemic to the Molt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93810] = { id = 93810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Masters' Perch", description = "Not every creature of the Void serves Xal'atath's whims. Conquest was our way long before her arrival.\n\nTo the north, you find Slayer's Rise. It is the vast battleground where three domanaar vie for power. And I hear your ren'dorei allies have set up in Masters' Perch, the main citadel, as well.\n\nI am certain great battles await you there. Go forth.", completion = "Good, we need more capable arms.", objectives = "Seek void elf allies in Masters' Perch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93811] = { id = 93811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Silvermoon Court", description = "The people of Quel'thalas appreciate your continued support. With threats on all sides, it is good to know we can rely on champions such as yourself to protect us.\n\nThe Court wishes to reward you for your efforts.", sourceObjective = "Speak with Caeris Fairdawn at Saltheril's Haven.", sourceObjectiveStatus = "unverified-source-field" }
quests[93850] = { id = 93850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windrunner Spire: Haunting Melodies", description = "So much grief... So much pain. It binds us to this place.\n\nHis melodies once soothed us, but now they are drowned out by the din of violence.\n\nPlease help us. Follow the sound of the lyre. He will guide you.", progress = "Please... help us.", completion = "The pain, the fear... I can feel that music washing it all away.\n\nThank you, friend.", objectives = "Quell the restless spirits inside Windrunner Spire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93865] = { id = 93865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carve Your Way", description = "We permit the presence of your kind for one reason. Your willingness to fight. Show us the skills of mortal duelists.\n\nGo, find others of your kind. The pit below is an ideal site for demonstrations of combat prowess.", progress = "Go. Show me a bout.", completion = "Good. But one victory proves nothing. The path to supremacy requires sustained practice.\n\nReturn tomorrow and demonstrate your skills further.", objectives = "Win a duel against another player or the Masters' Champion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93877] = { id = 93877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conditional Objectives - Sequential", description = "{name}! Glad to see you. The defenders in the fortress could use your help.\n\nOne of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on.\n\nShe needs the help of someone who can properly disrupt the robot's attacks so it can be repaired.\n\nDo you have a moment to help?", objectives = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93878] = { id = 93878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conditional Objectives - Multiple Steps, No Sequence", description = "{name}! Glad to see you. The defenders in the fortress could use your help.\n\nOne of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on.\n\nShe needs the help of someone who can properly disrupt the robot's attacks so it can be repaired.\n\nDo you have a moment to help?", objectives = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93879] = { id = 93879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conditional Objectives - Conditional After Sequence", description = "{name}! Glad to see you. The defenders in the fortress could use your help.\n\nOne of the gnomes built a robot to try to help defend the keep. However, it goes haywire every time it turns on.\n\nShe needs the help of someone who can properly disrupt the robot's attacks so it can be repaired.\n\nDo you have a moment to help?", objectives = "Activate Fightbot 11.2.7, then interrupt its abilities with your Felguard or Felhunter 1 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93889] = { id = 93889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Saltheril's Soiree", description = "Champion, you would do well to attend Saltheril's Soiree.\n\nThere, amidst Silvermoon's intricate politics and quiet struggles for influence, our most distinguished military orders each have matters they wish to see addressed.\n\nProve your worth to these factions, and you may find their gratitude and favor richly rewarded.", completion = "You've done well to navigate the Court without being swallowed by its politics. Silvermoon needs those who can act with purpose, not those lost in the machinery of ambition.", objectives = "Participate in Saltheril's Soiree and earn favor with one of the Silvermoon factions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93890] = { id = 93890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Abundance", description = "The trolls of Zul'Aman draw their strength from the loa: ancient spirits that grant power to those who honor them. These boons can be wondrous or perilous, depending on the loa's nature and the devotion of its followers.\n\nThere are whispers of a Loa of Abundance dwelling within Zul'Aman, its blessings said to bring prosperity to those deemed worthy.\n\nSeek it out, learn what drives it, and see if its favor would serve our cause.You will learn:", objectives = "Participate in Zul'Aman's Abundance Harvest and gain Loa's favor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93891] = { id = 93891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Legends of the Haranir", description = "For the Haranir, art is a language of memory. \n\nTheir history endures not in words but in vivid stories painted upon stone with pigments imbued with power. Through these works, the Zur'ashar, their revered historians, entwine living visions of the past to the present. Each vision draws us deeper into the haranir's mysteries, guiding us closer to the truths that shaped their world.You will learn:", sourceObjective = "Step into the memories of the Haranir through the enchanted paintings.", sourceObjectiveStatus = "unverified-source-field" }
quests[93892] = { id = 93892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Stormarion Assault", description = "The fight against Xal'atath tests our resolve, but it will not break us.\n\nVoid anomalies twist the halls of Stormarion Citadel, but they will find no weakness here. The Void Elves stand as our allies. Prove to our enemies that our strength when united is beyond the reach of even the Void.\n\nGo, {name}--aid them, and see the Citadel cleansed of corruption.You will learn:", objectives = "Participate in the Stormarion Assault event.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93899] = { id = 93899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slayer's Rise", description = "We've received reports of escalated troubles between some domanaar. Go investigate the battle in Slayer's Rise, then report to Deminos Darktrance in Masters' Perch.", completion = "{name}, you made it through. Well done.", objectives = "Complete the Slayer's Rise battleground.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93904] = { id = 93904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defying Gravity", description = "Now, we descend. The Void energy below is unlike any I've felt before, as if gravity itself yields to the Void. Once you enter the cave, its influence will be upon you.\n\nKalgorg has already slain and claimed power from the creatures within. Their violent deaths have left behind some kind of cursed terrain. But we must proceed and claim the power within. Fill the reliquary to the brim. \n\nI know not what to expect from my voidwalker. We will need all the power we can manage.", objectives = "Gather Void energy within the Lair of Predaxas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93905] = { id = 93905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ongoing Stoppage", description = "The Shadowguard may once have defied Xal'atath, but they're part of her army now. Whatever they're doing with the energies gathered here must be stopped.\n\nPut down their soldiers, harvesters, and machines. I'll do the same, and meet you deeper within.", objectives = "Slay Shadowguard and disrupt the Manaforge at the Ethereum Refinery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93909] = { id = 93909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Delves", description = "Many have ventured into the delves' depths, but few have returned with more than dust and bruises.\n\nValeera Sanguinar has taken a keen interest in these ventures. She leaves no stone unturned and has a remarkable talent for getting in to places others cannot.\n\nSeek her out, and see what fortune or danger awaits beneath the surface.", progress = "Stay sharp, {name}.", completion = "You've braved the delves and returned stronger for it.\n\nValeera was right--opportunity favors the bold.", objectives = "Complete 3 Delves in Midnight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93910] = { id = 93910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Prey", description = "Silvermoon is beset on all sides by threats both known and unknown. There are those who seek to track these threats and put an end to the strife and chaos they create.\n\nSpeak with Magister Astalor Bloodsworn in Murder Row. He will guide you toward the urgent threats.You will learn:", objectives = "Complete Prey Hunts for Astalor Bloodsworn in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93911] = { id = 93911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Dungeons", description = "The dungeons of Azeroth hold great challenges and even greater rewards. Within them lay treasures that may aid you in battles yet to pass, and powerful foes to overcome.\n\nEnter the dungeon, and see what awaits you there.", progress = "Be ready for anything. Fortune often walks hand in hand with peril.", completion = "You've proven your mettle once more. \n\nMay your victories within strengthen you for what lies ahead.", objectives = "Complete any Seasonal Dungeon at Normal difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93912] = { id = 93912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: Raid", description = "Gather your allies, you will face the great trials ahead. \n\nThe rewards are vast, and can aid you in the battles ahead. You and your allies need only vanquish a small number of these terrible foes.You will learn:", sourceObjective = "Defeat any 2 raid bosses in Midnight on any difficulty.", sourceObjectiveStatus = "unverified-source-field" }
quests[93913] = { id = 93913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Midnight: World Boss", description = "Powerful enemies roam Azeroth, their strength growing with each passing battle.\n\nOnly through courage and unity will you emerge victorious.You will learn:", sourceObjective = "Defeat a World Boss in Midnight.", sourceObjectiveStatus = "unverified-source-field" }
quests[93922] = { id = 93922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Singular Focus Unleashed", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93923] = { id = 93923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tenacity of the Shul'ka", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93924] = { id = 93924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unrelenting March", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93929] = { id = 93929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The War Within Recap", description = "<A parchment reaches you from an unknown sender.>\n\n<It speaks of perusing a tome to catch up on current events, and how it is vital to understand a looming threat.>\n\n<Perhaps you should seek out this tome to understand more when you are ready.>", completion = "<The tome floats in front of you. Its pages are filled with knowledge of all that has happened.>", objectives = "Consult the Tome of History to learn about the War Within saga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93930] = { id = 93930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Courting Success", description = "You seek an audience with Saltheril? And you're wearing... that? Excuse me for a moment while I laugh into my handkerchief.\n\n<Caeris laughs lightly behind his handkerchief.>\n\nNow, let me be professional. You are cordially invited to attend Saltheril's soiree.\n\nDon't embarrass yourself, {name}. The best of Silvermoon are watching.", completion = "I half expected you to run back home in tears! I hope you had a stunning time.", objectives = "Participate in Saltheril's Soiree and empower Eversong's runestones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93931] = { id = 93931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Abundance of Wealth", description = "De Loa of Abundance may not be one of de four great ones, but his worshippers are certainly de most devout.\n\nSeek him out yaself. You can find him in northern Zul'Aman near Halazzi's Temple, but I also hear he's established harvest sites in Eversong Woods, Harandar, and even de land of Void through de gargantuan skymouth.\n\nIf nothing else, de rewards he grants are glorious--to de worthy, at least.", progress = "Did you find de loa, hash'ura?", completion = "Heh! So ya finally met Dundun.\n\nEven de smallest are some of de greatest among de loa!", objectives = "Harvest wealth for the Loa of Abundance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93932] = { id = 93932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legendary Prosperity", description = "Harandar hides wisdom in every annal of its history, {name}. You would do well to seek out its legends for yourself. I suspect you may learn something of this world and our places in it.", completion = "I wonder what it is that the stones showed you. I hope you found it enlightening, {name}. But remember: there is always more to learn.", objectives = "Discover a legend of the Haranir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93933] = { id = 93933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guarded Treasures", description = "Our sojourn to this world has brought the ren'dorei an even deeper understanding of the Void than before. The domanaar with whom we share a common enemy are almost strangely generous with their knowledge. I believe they want us to become as fearsome as they are.\n\nThere is a Singularity Anchor in Stormarion Citadel. I have learned how to draw upon some of its power to craft you a powerful item.\n\nBut first, we must ensure it does not fall into the hands of our enemies.", progress = "Have you defended the anchor from the encroaching void forces?", completion = "Well done, {name}.", objectives = "Defend the Singularity Anchor in Stormarion Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93942] = { id = 93942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spark of Radiance", description = "A vision of radiance permeates your mind.\n\nEldara Dawnrunner might have more information regarding these Sparks of Radiance.", completion = "This is a Spark of Radiance.\n\nEvery week, one of these sparks will appear while on your adventures. In its current state, it's rather useless, but acquiring more will allow you to craft powerful items. Reagents like these are malleable, robust, and the prize for many crafters.\n\nThis is a unique crafting material that can help an item achieve expertise beyond that of mortal ability.", objectives = "Speak to Eldara Dawnrunner in Silvermoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93943] = { id = 93943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Curiosity: Combat", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important.>", objectives = "Use and equip a Combat Curio to your delve companion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93945] = { id = 93945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Curiosity: Utility", description = "<You hold the curio and discover a shimmering glow emanating from it. This looks important.>", objectives = "Use and equip a Utility Curio to your delve companion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93965] = { id = 93965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pet Wranglin'", description = "Seems like you've got the spurs for this ride. Just takes a little gettin' used to is all.\n\nCritters of all kind are crawling around Eversong and beyond. Cute, cuddly, creepy--whatever strikes your fancy.\n\nYou look tough enough to nab your own. Why don't ya give it a try?", completion = "You're back. Hope you found a critter you fancy.\n\nThere are plenty more where that came from. Reckon you'll wrangle 'em all? I leave that up to you.", objectives = "Capture a Wild Pet in any Midnight zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93969] = { id = 93969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call Shot", description = "Critters of all kind are crawling around Eversong and beyond. Cute, cuddly, creepy--whatever strikes your fancy.\n\nYa might be used to havin' varmints bash heads until one was weak enough to nab. Got a new way to try. All you need is a crate. You've got one, yeah?\n\nJust throw the crate from the start. It's mighty effective, I tell ya.\n\nYou look tough enough to nab your own. Why don't ya give it a try?", objectives = "Capture a Wild Pet in any Midnight zone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93970] = { id = 93970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Researching the Storm", description = "The urgent nature of our mission to these lands should not preclude us from embarking on new and meaningful research. Long have my people studied the void, and any opportunity to break new ground must be seized. \n\nOur scouts have been finding peculiar void manifestations throughout Voidstorm. If my hypothesis is correct, I believe we can use our host's facilities to further refine and understand these samples.", progress = "Please do not drop the sample.", completion = "Did you hear that? It most certainly did something! \n\nHuzzah!", objectives = "Help Anomander unlock the Research Console in Howling Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93979] = { id = 93979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lingering Memories", description = "Dimensius threatens us once more. There is no one who knows his methods better than his former Harbinger, Xal'atath. I would not say we can trust her, but we can work with her. She fears the All-Devouring's wrath after her betrayal.\n\nWe can't afford to turn away any potential ally. Think how many we will save from the Void Lord's hunger. Get your bearings in this city the four of us saved together. I will convince Alleria.", completion = "This is what we are fighting for, {name}. We can only save fragments of K'aresh, but we can prevent other worlds from sharing our dreadful fate.", objectives = "Meet Alleria and Locus-Walker at the docks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93997] = { id = 93997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Post Control", description = "Vidious is moving to claim Slayer's Rise, sending his proxies to occupy the Void Posts. I shall not be outmaneuvered.\n\nSeize full control of each of the Void Posts and eliminate any of Vidious's forces that try to stop you.", completion = "You have done well. Your loyalty has earned you a great prize.", objectives = "Enter War Mode and seize full control of each of the Void Posts in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[93999] = { id = 93999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Void Post Control", description = "Ziadan vies for control of Slayer's Rise, sending her proxies out to seize the Void Posts. Show her two can play at this game.\n\nStrike quickly: seize control of the Void Posts, slaying any who stand in your way.", completion = "A difficult task, completed with skill. Your loyalty deserves a reward.", objectives = "Enter War Mode and seize full control of each of the Void Posts in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94005] = { id = 94005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stellar Stash" }
quests[94012] = { id = 94012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Lil' Strider", description = "Howdy, pardner. Folks at this here pet store asked for my help straighten' out this place. But while I was distracted, a hawkstrider chick I've been rearin' slipped out the front door. Prettiest purple plumes you ever did see.\n\nWould you do me the kindness of finding her and bringing her back for me? I take her for a stroll in the garden every so often. I'll betcha that's where you'll find her.", progress = "Ya find her?", completion = "Fine work. Even some of these handlers wouldn't have been able to track down that wily bird.", objectives = "Capture Tiff in the Gardens of Remembrance in Silvermoon City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94052] = { id = 94052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Domanaar's Plan", description = "If I am to defeat Ziadan, I need information.\n\nMaps, strategy scrolls, battle reports, anything that gives me an edge!\n\nScour the Hate Spire and nearby grounds. Search every chest and cut down guards to find the information I need.", progress = "Have you obtained the battle plans?", completion = "This information shall give me the edge in the upcoming battles.", objectives = "Enter War Mode and collect 6 Ziadan's Battleplans from chests or slain guards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94055] = { id = 94055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Domanaar's Plan", description = "To counter Vidious' foul plans, I need information.\n\nMaps, strategy scrolls, battle reports, anything that turns the battle in my favor!\n\nScour the Grief Spire and nearby grounds. Search every chest and cut down guards to find the information I need.", progress = "Have you obtained the battle plans?", completion = "This information shall give me the edge in the upcoming battles.", objectives = "Enter War Mode and collect 6 Vidious' Battleplans from chests or slain guards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94056] = { id = 94056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Golden Pull", description = "A unique and valuable gift has been sent to me, hidden in the supply crates that drop upon Slayer's Rise. \n\nShould Ziadan obtain this gift instead, her insufferable gloating would never cease!\n\nEnter War Mode, and seize control of a supply crate. Then recover the gift for me!", progress = "Have you obtained my gift?", completion = "This gift honors me, I knew you would succeed in obtaining it.", objectives = "Enter War Mode and collect the Golden Vidious Card from a War Supply Crate in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94057] = { id = 94057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Golden Pull", description = "A unique and valuable gift has been sent to me, hidden in the supply crates that drop upon Slayer's Rise.\n\nShould Vidious obtain this gift instead, his taunts would be incessant.\n\nEnter War Mode, and seize control of a supply crate. Then recover the gift for me!", progress = "Have you obtained my gift?", completion = "This gift honors me, I knew you would succeed in obtaining it.", objectives = "Enter War Mode and collect the Golden Ziadan Card from a War Supply Crate in Slayer's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94058] = { id = 94058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissary of the Amani Tribe" }
quests[94210] = { id = 94210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feathering the Nest", description = "A house isn't quite a home without the perfect furnishings. It looked like there were some vendors in town. Perhaps it would be worth checking what they have in stock.", progress = "Have you met all the local vendors? They have some great furnishings available.", completion = "Did you find any good pieces for your house? We hope to have more vendors visit in the future, so be sure to check back often!", objectives = "Learn where to obtain Decor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94361] = { id = 94361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Abundant Life", description = "You are ready, acolyte! Ready to spread your wings or what have you?\n\nI have projected my presence into today's most active and tumultuous lands, rummaging about their natures and environs for areas ripe with abundance. With a little provocation from me, these forgotten corners are blooming bright with glorious harvestables!\n\nSeek me out! A crypt of phantasms in Eversong! A grove of verdant flora in Harandar! Even a quarry of living rock in Voidstorm! And, of course, right here too!", progress = "Temperance, acolyte.\n\nThere is still more abundance to be collected yet.", completion = "Well done, fellow acolyte!\n\nLet our harvests be bountiful, our rewards glorious, and our lives abundant!", objectives = "Complete each Abundance event once. They are located in Eversong, Zul'Aman, Harandar, and Voidstorm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94363] = { id = 94363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gloves Are Off", description = "If you've found yourself an invite you'll be wanting to put it to good use, no?\n\nUse your Blood-Soaked Invitation first then talk to a Bouncer in the Brawlpub and get to brawling!", objectives = "Talk to a Bouncer in Bizmo's Brawlpub in the Deeprun Tram after using your Blood-Soaked Invitation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94370] = { id = 94370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slithering Closer", description = "Do you bring tidings from Numia? She was supposed to be here and help me assess these fair flowers.\n\nShe must be occupied. The naga have encroached on my town and hers... they have kept to the beach so far, but that could change quickly.\n\nWill you check on my friend?", completion = "I will make it up to Fern. Thanks for speaking with her.\n\nAnd now, will you help me subdue this typical Farstrider? Nearly decapitated by a snapdragon, and he's acting like he just finished lunch!", objectives = "Find Numia Golden in Goldenmist Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94371] = { id = 94371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ranger's Dream", description = "Apprentices! Who can keep them tied down?\n\nTaemin was a particularly talented arcanist, but his head was always in the clouds. Or in the woods, really.\n\nInstead of studying, he buried his nose in storybooks! The legends of Eversong! The Rangers of old! Heroes of the Sin'dorei! He couldn't get enough, the dreaming fool!\n\nAnd now... no, he's not dead. Did I imply that?\n\nHe's just run off to join the Farstriders. Check in on him, won't you? See if he's come to his senses?", completion = "It was good of you to check on me, but I'm committed to the Farstriders!", objectives = "Check in on Arcanist Taemin at Farstrider Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[94372] = { id = 94372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gloves Are Off", description = "If you've found yourself an invite you'll be wanting to put it to good use, no?\n\nUse your Blood-Soaked Invitation first then talk to a Grunt in the Brawl'gar Arena and get to brawling!", objectives = "Talk to a Grunt in the Brawl'gar Arena in Orgrimmar after using your Blood-Soaked Invitation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
